+  describe("findByUserAndTeam", () => {
+    it("returns the membership when it exists", async () => {
+      const team = await createTeam();
+      const user = await createUser({ teamId: team.id });
+      const membership = await createTeamMembership({
+        teamId: team.id,
+        userId: user.id,
+        role: MEMBER_ROLE.OWNER,
+      });
+
+      const found = await findByUserAndTeam(user.id, team.id);
+      assert.equal(found?.id, membership.id);
+      assert.equal(found?.role, MEMBER_ROLE.OWNER);
+    });
+
+    it("returns null when there is no membership", async () => {
+      const team = await createTeam();
+      const user = await createUser({ teamId: team.id });
+
+      assert.equal(await findByUserAndTeam(user.id, team.id), null);
+    });
+  });
+
+  describe("listByUserWithTeam", () => {
+    it("returns the user's memberships with the team name, excluding others", async () => {
+      const team = await createTeam();
+      const user = await createUser({ teamId: team.id });
+      await createTeamMembership({
+        teamId: team.id,
+        userId: user.id,
+        role: MEMBER_ROLE.OWNER,
+      });
+      await createTeamMembership();
+
+      const memberships = await listByUserWithTeam(user.id);
+
+      assert.equal(memberships.length, 1);
+      assert.equal(memberships[0].teamId, team.id);
+      assert.equal(memberships[0].team.name, team.name);
+    });
+
+    it("orders memberships by creation time ascending", async () => {
+      const user = await createUser();
+      const older = await createTeam();
+      const newer = await createTeam();
+      await createTeamMembership({
+        teamId: older.id,
+        userId: user.id,
+        role: MEMBER_ROLE.MEMBER,
+        createdAt: new Date("2020-01-01"),
+      });
+      await createTeamMembership({
+        teamId: newer.id,
+        userId: user.id,
+        role: MEMBER_ROLE.MEMBER,
+        createdAt: new Date("2020-06-01"),
+      });
+
+      const memberships = await listByUserWithTeam(user.id);
+      assert.deepEqual(
+        memberships.map((m) => m.teamId),
+        [older.id, newer.id]
+      );
+    });
+
+    it("returns an empty list when the user has no memberships", async () => {
+      const user = await createUser();
+      assert.deepEqual(await listByUserWithTeam(user.id), []);
+    });
+  });
+
+  describe("create", () => {
+    it("creates a membership with the given role", async () => {
+      const team = await createTeam();
+      const user = await createUser({ teamId: team.id });
+
+      const membership = await create({
+        userId: user.id,
+        teamId: team.id,
+        role: MEMBER_ROLE.MEMBER,
+      });
+
+      assert.equal(membership.userId, user.id);
+      assert.equal(membership.teamId, team.id);
+      assert.equal(membership.role, MEMBER_ROLE.MEMBER);
+    });
+  });
+
+  describe("deleteByUserAndTeam", () => {
+    it("removes the membership row", async () => {
+      const team = await createTeam();
+      const user = await createUser({ teamId: team.id });
+      await createTeamMembership({
+        teamId: team.id,
+        userId: user.id,
+        role: MEMBER_ROLE.OWNER,
+      });
+
+      await deleteByUserAndTeam(user.id, team.id);
+
+      assert.equal(
+        await prisma.teamMembership.findUnique({
+          where: { userId_teamId: { userId: user.id, teamId: team.id } },
+        }),
+        null
+      );
+    });
+  });
 });

