+export async function findByUserAndTeam(userId: string, teamId: string) {
+  return await prisma.teamMembership.findUnique({
+    where: { userId_teamId: { userId, teamId } },
+  });
+}
+
+export async function listByUserWithTeam(userId: string) {
+  return await prisma.teamMembership.findMany({
+    where: { userId },
+    select: {
+      id: true,
+      teamId: true,
+      role: true,
+      createdAt: true,
+      team: { select: { id: true, name: true } },
+    },
+    orderBy: { createdAt: "asc" },
+  });
+}
+
+export async function create(input: {
+  userId: string;
+  teamId: string;
+  role: MEMBER_ROLE;
+}) {
+  return await prisma.teamMembership.create({ data: input });
+}
+
+export async function deleteByUserAndTeam(userId: string, teamId: string) {
+  return await prisma.teamMembership.delete({
+    where: { userId_teamId: { userId, teamId } },
+  });
+}

