@@ -45,6 +45,32 @@ export async function findById(userId: string) {
   return await prisma.user.findUnique({ where: { id: userId } });
 }

+export async function findByIdOrEmail(idOrEmail: string) {
+  const rows = await prisma.$queryRaw<
+    {
+      id: string;
+      email: string | null;
+      name: string | null;
+      teamId: string;
+      accessEnabled: boolean;
+    }[]
+  >`
+    SELECT id, email, name, "teamId", "accessEnabled"
+    FROM "User"
+    WHERE id = ${idOrEmail} OR lower(email) = lower(${idOrEmail})
+    LIMIT 1
+  `;
+  return rows.at(0) ?? null;
+}
+
+export async function updateActiveTeam(userId: string, teamId: string) {
+  return await prisma.user.update({
+    where: { id: userId },
+    data: { teamId },
+    select: { id: true, teamId: true },
+  });
+}
+
 export async function deleteById(userId: string) {
   return await prisma.user.delete({ where: { id: userId } });
 }
